#include <iostream>
#include <stdexcept>
#include <string>

class ResourceTracker {
public:
    explicit ResourceTracker(std::string name) : name_(std::move(name)) {
        std::cout << "Constructed: " << name_ << '\n';
    }
    ~ResourceTracker() {
        std::cout << "Destructed: " << name_ << '\n';
    }
private:
    std::string name_;
};

void innerFunction() {
    ResourceTracker r1("inner-local");
    std::cout << "Throwing std::runtime_error from innerFunction\n";
    throw std::runtime_error("Critical hardware fault");
}

void intermediateFunction() {
    ResourceTracker r2("intermediate-local");
    try {
        innerFunction();
    } catch (const std::exception& ex) {
        std::cout << "Intermediate log: " << ex.what() << " - rethrowing...\n";
        throw; // Rethrow exact original exception
    }
}

int main() {
    try {
        intermediateFunction();
    } catch (const std::runtime_error& err) {
        std::cout << "Main caught runtime_error: " << err.what() << '\n';
    }
    std::cout << "Program resumed normally after try-catch\n";
    return 0;
}

#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>

class CustomModuleError : public std::runtime_error {
public:
    explicit CustomModuleError(const std::string& msg)
        : std::runtime_error("Module Error: " + msg) {}
};

struct DynamicData {
    int id;
    DynamicData(int i) : id(i) { std::cout << "Data " << id << " allocated\n"; }
    ~DynamicData() { std::cout << "Data " << id << " safely freed by RAII\n"; }
};

void riskyOperation(int trigger) {
    auto safePtr = std::make_unique<DynamicData>(42);

    if (trigger == 1) {
        throw CustomModuleError("Invalid internal state");
    } else if (trigger == 2) {
        throw std::out_of_range("Index out of bounds");
    }

    std::cout << "Normal completion for id: " << safePtr->id << '\n';
}

int main() {
    // Test polymorphic catch and RAII cleanup
    for (int testCase = 1; testCase <= 2; ++testCase) {
        std::cout << "--- Running test case " << testCase << " ---\n";
        try {
            riskyOperation(testCase);
        } catch (const CustomModuleError& cme) {
            std::cout << "Caught specific: " << cme.what() << '\n';
        } catch (const std::exception& baseEx) {
            std::cout << "Caught base exception: " << baseEx.what() << '\n';
        }
    }
    return 0;
}
